    dt = datetime.strptime(f"2005-{groups[0]}-{groups[1]} {groups[2]}:{groups[3]}:{groups[4]}.{groups[5]}", "%Y-%m-%d %H:%M:%S.%f")
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': []}

def inverse(record):
    micros = int(record['stored'][0])
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime("2005-%m-%d-%H.%M.%S.%f")

